syntax:
For member function pointers:
typedef ReturnType (ClassName::*PointerName)(ParameterTypes);

For conversion operators:
operator TargetType() const;

For pointer-to-member-data (DANGEROUS):
DataType ClassName::* pointer_name = &ClassName::member_name;
obj.*pointer_name = value;  // Bypasses private access!

Example:
struct S {
    operator ReturnType (S::*)(ParameterTypes)() const;
};

code_example:
#include <iostream>
struct S {
    // Conversion operator to member function pointer type
    operator void (S::*)(long) const {
        return &S::fn;
    }
    // Member function
    void fn(long l) const {
        std::cout << "fn called with " << l << std::endl;
    }
    // Conversion operator to data member pointer
    operator char S::*() const {
        return &S::data;
    }
    char data = 'A';
};
typedef void (S::*PMF)(long) const;
typedef char S::*PMD;

int main() {
    S s;
    // Using conversion operator to get member function pointer
    PMF pmf = s;
    (s.*pmf)(42); // Calls s.fn(42)
    // Using conversion operator to get data member pointer
    PMD pmd = s;
    std::cout << "Data member value: " << s.*pmd << std::endl;
    return 0;
}
